package com.anssa8bu.ssafy.common.redis.repository; import com.anssa8bu.ssafy.common.redis.*; import com.anssa8bu.ssafy.common.redis.dto.ActiveTrainingProfileCache; import org.springframework.data.redis.core.StringRedisTemplate; import org.springframework.stereotype.Repository; import java.time.Duration; import java.util.Optional; @Repository public class TrainingProfileCacheRepository{private final StringRedisTemplate redis;private final RedisJsonCodec codec;private final RedisKeyGenerator keys;public TrainingProfileCacheRepository(StringRedisTemplate r,RedisJsonCodec c,RedisKeyGenerator k){redis=r;codec=c;keys=k;}public void save(ActiveTrainingProfileCache v,Duration ttl){redis.opsForValue().set(keys.activeTrainingProfile(),codec.encode(v),ttl);}public Optional<ActiveTrainingProfileCache> find(){String j=redis.opsForValue().get(keys.activeTrainingProfile());return j==null?Optional.empty():Optional.of(codec.decode(j,ActiveTrainingProfileCache.class));}public void delete(){redis.delete(keys.activeTrainingProfile());}}
